package android.content.res;
import java.io.ByteArrayInputStream;import java.io.FileNotFoundException;import java.io.InputStream;import java.io.IOException;import java.util.LinkedHashMap;import java.util.Map;import dev.mixer.android.ConcreteHostProbe;
public class AssetManager {public static final int ACCESS_STREAMING=2;public final Map<String,byte[]> assets=new LinkedHashMap<>();public Throwable failure;public int opens;public void put(String name,byte[] bytes){assets.put(name,bytes.clone());}public InputStream open(String name,int mode)throws IOException{ConcreteHostProbe.hit("AssetManager.open","entry",this);opens++;ConcreteHostProbe.fail(failure);byte[] bytes=assets.get(name);if(bytes==null)throw new FileNotFoundException(name);InputStream result=new ByteArrayInputStream(bytes);ConcreteHostProbe.hit("AssetManager.open","beforeReturn",this);return result;}public InputStream open(String name)throws IOException{return open(name,ACCESS_STREAMING);}}
